package local.tvmorph.tv;
import org.json.*;import java.net.*;import java.io.*;import java.util.*;
/** Stalker/Ministra client. Session token and provider commands stay native. */
final class PortalSource {
 final JSONObject config;private final String endpoint,mac;private String token="";private long authenticated;
 private final Map<String,String> commands=new LinkedHashMap<>();
 static JSONObject normalize(JSONObject input)throws Exception{
  JSONObject out=new JSONObject(input.toString());String address=input.optString("server").trim();if(!address.contains("://"))address="http://"+address;
  URI u=new URI(address);if(!Arrays.asList("http","https").contains(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null||u.getQuery()!=null||u.getFragment()!=null)throw new IOException("Enter a valid Portal URL including its port.");
  String mac=input.optString("mac").trim().replace('-',':').toUpperCase(Locale.ROOT);if(!mac.matches("(?:[0-9A-F]{2}:){5}[0-9A-F]{2}"))throw new IOException("Enter the MAC address registered with your provider: 00:1A:79:12:34:56");
  String path=u.getPath().replaceAll("/+$","");if(path.endsWith("/c"))path=path.substring(0,path.length()-2);if(path.endsWith("/server/load.php"))path=path.substring(0,path.length()-16);else if(path.endsWith("/portal.php"))path=path.substring(0,path.length()-11);
  out.put("type","portal").put("server",u.getScheme()+"://"+u.getRawAuthority()+path).put("mac",mac).put("username","").put("password","").put("publicMode",false);return out;
 }
 PortalSource(JSONObject input)throws Exception{config=normalize(input);mac=config.getString("mac");String base=config.getString("server");endpoint=base+(base.endsWith("/stalker_portal")?"/server/load.php":"/portal.php");}
 private Object request(String type,String action,String... pairs)throws Exception{
  StringBuilder url=new StringBuilder(endpoint+"?type="+Xtream.enc(type)+"&action="+Xtream.enc(action)+"&JsHttpRequest=1-xml");for(int i=0;i+1<pairs.length;i+=2)url.append('&').append(Xtream.enc(pairs[i])).append('=').append(Xtream.enc(pairs[i+1]));
  HttpURLConnection c=(HttpURLConnection)new URL(url.toString()).openConnection();try{c.setConnectTimeout(8000);c.setReadTimeout(18000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","Mozilla/5.0 (QtEmbedded; U; Linux; C) AppleWebKit/533.3 MAG200 stbapp ver: 2 rev: 250 Safari/533.3");c.setRequestProperty("X-User-Agent","Model: MAG254; Link: WiFi");c.setRequestProperty("Cookie","mac="+Xtream.enc(mac)+"; stb_lang=en; timezone=GMT");c.setRequestProperty("Referer",config.getString("server")+"/c/");if(!token.isEmpty())c.setRequestProperty("Authorization","Bearer "+token);int status=c.getResponseCode();if(status==401||status==403)throw new IOException("Portal authorization refused. Check the registered MAC and subscription.");if(status!=200)throw new IOException("Portal request failed (HTTP "+status+").");ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>24*1024*1024)throw new IOException("Portal response is too large.");out.write(b,0,n);}}Object value=new JSONTokener(out.toString("UTF-8")).nextValue();if(!(value instanceof JSONObject)||!((JSONObject)value).has("js"))throw new IOException("Invalid Portal response. Check the full Portal path.");Object js=((JSONObject)value).opt("js");if(js==null||js==JSONObject.NULL||Boolean.FALSE.equals(js))throw new IOException("Portal refused this request. Check provider device requirements.");return js;}finally{c.disconnect();}
 }
 synchronized JSONObject auth()throws Exception{
  token="";Object hello=request("stb","handshake","token","");if(!(hello instanceof JSONObject)||(token=((JSONObject)hello).optString("token")).isEmpty())throw new IOException("Portal did not return a session token.");
  Object profile=request("stb","get_profile","hd","1","stb_type","MAG254","num_banks","2","image_version","218","auth_second_step","0");if(!(profile instanceof JSONObject))throw new IOException("Portal profile unavailable.");JSONObject p=(JSONObject)profile;if(p.optInt("blocked",0)==1||p.optInt("status",0)==1)throw new IOException("Portal subscription is blocked or inactive.");authenticated=System.currentTimeMillis();JSONObject result=new JSONObject().put("connected",true).put("name",config.optString("name","My Portal")).put("status","Active").put("expires","").put("live",config.optBoolean("live",true)).put("vod",config.optBoolean("vod",true)).put("series",config.optBoolean("series",true));
  try{Object info=request("account_info","get_main_info");if(info instanceof JSONObject){JSONObject a=(JSONObject)info;String expiry=a.optString("end_date",a.optString("expire_billing_date",""));if(expiry.matches("[0-9]{9,13}"))result.put("expires",expiry);else if(!expiry.isEmpty())result.put("providerExpiry",expiry);}}catch(IOException optional){}return result;
 }
 private void session()throws Exception{if(token.isEmpty()||System.currentTimeMillis()-authenticated>240000)auth();}
 private String type(String kind){return kind.equals("live")?"itv":kind.equals("series")?"series":"vod";}
 synchronized JSONArray categories(String kind)throws Exception{session();Object raw=request(type(kind),kind.equals("live")?"get_genres":"get_categories");JSONArray source=raw instanceof JSONArray?(JSONArray)raw:new JSONArray(),out=new JSONArray();for(int i=0;i<source.length();i++){JSONObject r=source.optJSONObject(i);if(r!=null)out.put(new JSONObject().put("category_id",r.optString("id")).put("category_name",r.optString("title",r.optString("name"))));}return out;}
 private JSONArray data(Object raw){if(raw instanceof JSONArray)return (JSONArray)raw;if(raw instanceof JSONObject){JSONArray rows=((JSONObject)raw).optJSONArray("data");if(rows!=null)return rows;}return new JSONArray();}
   synchronized JSONObject listPage(String kind,String category,int pageNum)throws Exception{session();JSONArray out=new JSONArray();Set<String> seen=new HashSet<>();Object raw=request(type(kind),"get_ordered_list",kind.equals("live")?"genre":"category",category.isEmpty()?"*":category,"p",String.valueOf(Math.max(1,pageNum)),"sortby","number");JSONArray rows=data(raw);for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);if(r==null)continue;String id=r.optString("id");if(!id.matches("[0-9]{1,14}")||!seen.add(id))continue;String command=r.optString("cmd");if(!command.isEmpty())remember(kind+":"+id,command);String image=r.optString("screenshot_uri",r.optString("logo",r.optString("cover","")));out.put(new JSONObject().put("id",id).put("name",r.optString("name",r.optString("title","Untitled"))).put("kind",kind).put("category",r.optString("tv_genre_id",r.optString("category_id",category))).put("icon",image).put("ext","mp4").put("added",r.optLong("added",0)));}int total=raw instanceof JSONObject?((JSONObject)raw).optInt("total_items",out.length()):out.length();return new JSONObject().put("rows",out).put("total",Math.max(total,out.length()));}
  synchronized JSONArray list(String kind,String category)throws Exception{session();JSONArray out=new JSONArray();int page=1,total=Integer.MAX_VALUE;Set<String> seen=new HashSet<>();while(out.length()<total){Object raw=request(type(kind),"get_ordered_list",kind.equals("live")?"genre":"category",category.isEmpty()?"*":category,"p",String.valueOf(page),"sortby","number");JSONArray rows=data(raw);if(rows.length()==0)break;int added=0;for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);if(r==null)continue;String id=r.optString("id");if(!id.matches("[0-9]{1,14}")||!seen.add(id))continue;added++;String command=r.optString("cmd");if(!command.isEmpty())remember(kind+":"+id,command);String image=r.optString("screenshot_uri",r.optString("logo",r.optString("cover","")));out.put(new JSONObject().put("id",id).put("name",r.optString("name",r.optString("title","Untitled"))).put("kind",kind).put("category",r.optString("tv_genre_id",r.optString("category_id",category))).put("icon",image).put("ext","mp4").put("added",r.optLong("added",0)));}if(added==0)break;if(raw instanceof JSONObject)total=((JSONObject)raw).optInt("total_items",out.length());else break;if(++page>1000)throw new IOException("Portal catalog exceeded its page limit. Open a category instead.");}return out;}
 private void remember(String key,String command){commands.put(key,command);while(commands.size()>50000)commands.remove(commands.keySet().iterator().next());}
 private String episodeId(String series,String season,String number)throws Exception{byte[] h=java.security.MessageDigest.getInstance("SHA-256").digest((series+":"+season+":"+number).getBytes("UTF-8"));long n=0;for(int i=0;i<6;i++)n=(n<<8)|(h[i]&255L);return String.valueOf(n>>>2);}
 synchronized JSONArray episodes(String id)throws Exception{session();Object raw=request("series","get_ordered_list","movie_id",id,"season_id","0","episode_id","0","p","1");JSONArray source=data(raw),out=new JSONArray();for(int i=0;i<source.length();i++){JSONObject r=source.optJSONObject(i);if(r==null)continue;JSONArray eps=r.optJSONArray("series");if(eps==null)continue;String season=r.optString("id","1"),cmd=r.optString("cmd",commands.get("series:"+id));for(int j=0;j<eps.length();j++){String number=String.valueOf(eps.opt(j));if(!number.matches("[0-9]{1,6}"))continue;String eid=episodeId(id,season,number);remember("episode:"+id+":"+eid,cmd+"\n"+number);out.put(new JSONObject().put("id",eid).put("kind","episode").put("name","S"+season+" E"+number).put("season",season).put("episode",Integer.parseInt(number)).put("seriesId",id).put("category",id).put("ext","mp4"));}}return out;}
 synchronized String stream(JSONObject item)throws Exception{session();String kind=item.optString("kind"),id=item.optString("id"),parent=item.optString("seriesId",item.optString("category"));String key=kind.equals("episode")?"episode:"+parent+":"+id:kind+":"+id;String cmd=commands.get(key);if(cmd==null){if(kind.equals("episode"))episodes(parent);else list(kind,item.optString("category"));cmd=commands.get(key);}if(cmd==null||cmd.isEmpty())throw new IOException("Portal playback command unavailable. Refresh this category.");String episode="";int split=cmd.indexOf('\n');if(split>=0){episode=cmd.substring(split+1);cmd=cmd.substring(0,split);}Object raw=request(type(kind.equals("episode")?"vod":kind),"create_link","cmd",cmd,"series",episode,"forced_storage","undefined","disable_ad","0","download","0");String resolved=raw instanceof JSONObject?((JSONObject)raw).optString("cmd"):"";resolved=resolved.replaceFirst("^(?:ffmpeg|ffrt|auto)\\s+","").trim();URI uri=new URI(resolved);if(!Arrays.asList("http","https").contains(uri.getScheme())||uri.getHost()==null)throw new IOException("Portal did not return a supported video link.");return resolved;}
 void clear(){commands.clear();}
}
